// One order: which side it is on, its limit price, and how much quantity remains unfilled.
class Order {
    String orderId;
    Side side;
    long price;
    long remainingQuantity;

    Order(String orderId, Side side, long price, long quantity) {
        this.orderId = orderId;
        this.side = side;
        this.price = price;
        this.remainingQuantity = quantity;
    }
}

// One completed match between a buy and a sell order.
class Trade {
    String buyOrderId;
    String sellOrderId;
    long price;
    long quantity;

    Trade(String buyOrderId, String sellOrderId, long price, long quantity) {
        this.buyOrderId = buyOrderId;
        this.sellOrderId = sellOrderId;
        this.price = price;
        this.quantity = quantity;
    }

    public String toString() {
        return "buy=" + buyOrderId + " sell=" + sellOrderId + " price=" + price + " qty=" + quantity;
    }
}

// A single-symbol, single-threaded order book and matching engine, enforcing
// price-time priority: best price matches first, and among equal prices,
// whichever order arrived earliest (first in the queue) matches first.
class MatchingEngine {
    // Bids: highest price first. Asks: lowest price first. Each price level is
    // its own first-in-first-out queue, preserving arrival order for ties.
    private final TreeMap<Long, Deque<Order>> bids = new TreeMap<>(Comparator.reverseOrder());
    private final TreeMap<Long, Deque<Order>> asks = new TreeMap<>();
    private final Map<String, Order> ordersById = new HashMap<>(); // for looking up remaining quantity by id

    // Submits a new order, matching it against the opposite side of the book
    // as far as possible, and resting any unfilled remainder in the book.
    List<Trade> submit(Order incoming) {
        ordersById.put(incoming.orderId, incoming);
        List<Trade> trades = new ArrayList<>();
        TreeMap<Long, Deque<Order>> oppositeSide = (incoming.side == Side.BUY) ? asks : bids;

        while (incoming.remainingQuantity > 0 && !oppositeSide.isEmpty()) {
            Map.Entry<Long, Deque<Order>> bestLevel = oppositeSide.firstEntry(); // best price on the opposite side
            long bestPrice = bestLevel.getKey();

            // A buy only matches at or below its limit price; a sell only matches at or above its limit price.
            boolean priceAcceptable = (incoming.side == Side.BUY) ? (bestPrice <= incoming.price) : (bestPrice >= incoming.price);
            if (!priceAcceptable) break; // no acceptable price left on this side; stop matching

            Deque<Order> queueAtLevel = bestLevel.getValue();
            Order resting = queueAtLevel.peekFirst(); // earliest-arrived order at this price level: time priority

            long fillQuantity = Math.min(incoming.remainingQuantity, resting.remainingQuantity);
            incoming.remainingQuantity -= fillQuantity;
            resting.remainingQuantity -= fillQuantity;

            String buyOrderId = (incoming.side == Side.BUY) ? incoming.orderId : resting.orderId;
            String sellOrderId = (incoming.side == Side.BUY) ? resting.orderId : incoming.orderId;
            trades.add(new Trade(buyOrderId, sellOrderId, bestPrice, fillQuantity)); // trade executes at the RESTING order's price

            if (resting.remainingQuantity == 0) {
                queueAtLevel.pollFirst(); // fully filled; remove from the front of the queue
                if (queueAtLevel.isEmpty()) {
                    oppositeSide.remove(bestPrice); // no orders left at this price level at all
                }
            }
        }

        if (incoming.remainingQuantity > 0) {
            // Unfilled remainder rests in the book, at the back of its own price level's queue.
            TreeMap<Long, Deque<Order>> sameSide = (incoming.side == Side.BUY) ? bids : asks;
            sameSide.computeIfAbsent(incoming.price, price -> new ArrayDeque<>()).addLast(incoming);
        }

        return trades;
    }

    long remainingQuantity(String orderId) {
        Order order = ordersById.get(orderId);
        return order == null ? 0 : order.remainingQuantity;
    }
}

