enum class Side { BUY, SELL };

// One order: which side it is on, its limit price, and how much quantity remains unfilled.
struct Order {
    std::string orderId;
    Side side;
    long long price;
    long long remainingQuantity;
};

// One completed match between a buy and a sell order.
struct Trade {
    std::string buyOrderId;
    std::string sellOrderId;
    long long price;
    long long quantity;

    std::string toString() const {
        return "buy=" + buyOrderId + " sell=" + sellOrderId + " price=" + std::to_string(price) + " qty=" + std::to_string(quantity);
    }
};

// A single-symbol, single-threaded order book and matching engine, enforcing
// price-time priority: best price matches first, and among equal prices,
// whichever order arrived earliest (first in the queue) matches first.
class MatchingEngine {
public:
    // Submits a new order, matching it against the opposite side of the book
    // as far as possible, and resting any unfilled remainder in the book.
    std::vector<Trade> submit(Order incoming) {
        Order* stored = &(ordersById_[incoming.orderId] = incoming);
        std::vector<Trade> trades;
        // Bids: highest price first. Asks: lowest price first. Each price level is
        // its own first-in-first-out queue, preserving arrival order for ties.
        auto& oppositeSide = (incoming.side == Side::BUY) ? asks_ : bids_;

        while (stored->remainingQuantity > 0 && !oppositeSide.empty()) {
            long long bestPrice = (incoming.side == Side::BUY) ? oppositeSide.begin()->first : oppositeSide.rbegin()->first;   // best price on the opposite side

            // A buy only matches at or below its limit price; a sell only matches at or above its limit price.
            bool priceAcceptable = (incoming.side == Side::BUY) ? (bestPrice <= stored->price) : (bestPrice >= stored->price);
            if (!priceAcceptable) break;   // no acceptable price left on this side; stop matching

            auto& queueAtLevel = oppositeSide[bestPrice];
            Order* resting = queueAtLevel.front();   // earliest-arrived order at this price level: time priority

            long long fillQuantity = std::min(stored->remainingQuantity, resting->remainingQuantity);
            stored->remainingQuantity -= fillQuantity;
            resting->remainingQuantity -= fillQuantity;

            std::string buyOrderId = (incoming.side == Side::BUY) ? stored->orderId : resting->orderId;
            std::string sellOrderId = (incoming.side == Side::BUY) ? resting->orderId : stored->orderId;
            trades.push_back({ buyOrderId, sellOrderId, bestPrice, fillQuantity });   // trade executes at the RESTING order's price

            if (resting->remainingQuantity == 0) {
                queueAtLevel.pop_front();   // fully filled; remove from the front of the queue
                if (queueAtLevel.empty()) {
                    oppositeSide.erase(bestPrice);   // no orders left at this price level at all
                }
            }
        }

        if (stored->remainingQuantity > 0) {
            // Unfilled remainder rests in the book, at the back of its own price level's queue.
            auto& sameSide = (incoming.side == Side::BUY) ? bids_ : asks_;
            sameSide[stored->price].push_back(stored);
        }

        return trades;
    }

    long long remainingQuantity(const std::string& orderId) {
        auto it = ordersById_.find(orderId);
        return it == ordersById_.end() ? 0 : it->second.remainingQuantity;
    }

private:
    // Bids ordered highest-first via reverse iteration; asks ordered lowest-first naturally.
    std::map<long long, std::deque<Order*>> bids_;
    std::map<long long, std::deque<Order*>> asks_;
    std::map<std::string, Order> ordersById_;   // for looking up remaining quantity by id, and owns storage
};

int main() {
    std::cout << std::boolalpha;
    MatchingEngine engine;

    // Two resting sell orders at different prices; S1 submitted before S2.
    engine.submit({ "S1", Side::SELL, 50, 100 });
    engine.submit({ "S2", Side::SELL, 49, 50 });

    // A buy order for 120 shares at 50: should match the better price (49) first, then 50.
    auto trades1 = engine.submit({ "B1", Side::BUY, 50, 120 });
    std::cout << "Trades from B1 (expects price priority, then a partial fill):\n";
    for (auto& t : trades1) std::cout << "  " << t.toString() << "\n";
    std::cout << "Remaining resting quantity for S1 at price 50: " << engine.remainingQuantity("S1") << "\n";

    // A third sell order at the same price as S1's remainder, submitted after it.
    engine.submit({ "S3", Side::SELL, 50, 20 });

    // A buy order for 40 shares at 50: should match S1's remainder FIRST (time priority), then S3.
    auto trades2 = engine.submit({ "B2", Side::BUY, 50, 40 });
    std::cout << "Trades from B2 (expects time priority: S1's remainder before S3):\n";
    for (auto& t : trades2) std::cout << "  " << t.toString() << "\n";
    std::cout << "Remaining resting quantity for S3 at price 50: " << engine.remainingQuantity("S3") << "\n";
    std::cout << "S1 fully filled and removed from the book: " << (engine.remainingQuantity("S1") == 0) << "\n";
    return 0;
}

